// Existing operator credentials establish a short-lived HttpOnly presenter session.
const button=document.createElement('button');button.className='language';button.textContent='Presenter sign-in';button.id='presenter-session';document.querySelector('.top-actions').prepend(button);
const dialog=document.createElement('dialog');dialog.innerHTML=`<form id="presenter-form" style="padding:28px;max-width:420px"><h2>Presenter access</h2><p>Sign in once to use live AI research, opportunity queries and file imports. Public catalogue search and pack exports remain available to everyone.</p><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p role="status" id="presenter-status"></p><button class="primary">Sign in</button> <button type="button" id="presenter-close" class="secondary">Cancel</button></form>`;document.body.append(dialog);
let authenticated=false;
async function check(){try{const r=await fetch('/api/session');if(!r.ok){button.hidden=location.hostname==='localhost'||location.hostname==='127.0.0.1';return}const j=await r.json();authenticated=j.authenticated;button.textContent=authenticated?'Presenter · sign out':'Presenter sign-in'}catch{}}
button.onclick=async()=>{if(authenticated){await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({logout:true})});location.reload()}else dialog.showModal()};
dialog.querySelector('#presenter-close').onclick=()=>dialog.close();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{const r=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.error);e.target.reset();location.reload()}catch(err){dialog.querySelector('#presenter-status').textContent=err.message}};check();
